impl Solution {
    pub fn lost_permutation(b: Vec<u32>, m: usize, s: u32) -> bool {
        let sum_b: u32 = b.iter().sum();
        let max_b = *b.iter().max().unwrap();

        // The target sum is sum_b + s
        let target_sum = sum_b + s;

        // We need to find n such that max_b <= n <= 100 and n*(n+1)/2 == target_sum
        // Solve n^2 + n - 2*target_sum = 0
        let discriminant = 1 + 8 * target_sum as i64;
        let sqrt_discriminant = (discriminant as f64).sqrt() as i64;

        if sqrt_discriminant * sqrt_discriminant != discriminant {
            return false;
        }

        let n1 = (-1 + sqrt_discriminant) / 2;
        let n2 = (-1 - sqrt_discriminant) / 2;

        let n = if n1 > 0 { n1 } else { n2 };

        max_b <= n && n <= 100 && n * (n + 1) / 2 == target_sum
    }
}

